import type { VisaItem, CountryVisas } from './fullVisaDatabase';

function getNorwayMicroDetails(code: string, cat: string, name: string) {
  let fundsMin = "Norway C Short Stay Tourist / Business Visas require proof of min NOK 500/day (approx EUR 45/day) + confirmed hotel reservation + return flight + travel medical insurance (min EUR 30,000).";
  let fundsBankMonths = "Last 3 to 6 months personal bank statements stamped by bank branch, showing liquid funds.";
  let fundsSudden = "❌ Sudden 1-day cash deposits right before visa submission at VFS Global / Norwegian Embassy are strictly flagged by UDI. Average balance must be maintained over 3-6 months.";
  let fundsEx = "✅ Sahi: Seasoned 3-6 month bank statement with NOK 500/day liquid equivalent. ❌ Galat: Borrowed lump sum deposited 24 hours prior to appointment.";

  let itrYears = "Income Tax Returns (ITR) or Tax Assessment (Skattemelding) for the past 2-3 years.";
  let itrMatch = "Reported tax income must reconcile with personal bank credits and employment contract.";
  let itrNoItr = "Not required for short-term visitors fully sponsored by Norwegian host or students sponsored by parents.";

  let bankMonths = "Last 3-6 months bank statements.";
  let bankReg = "Regular salary credits or corporate revenue.";
  let bankFd = "Fixed deposits accepted as supporting proof.";
  let bankSource = "Salary, business revenue, or verified sponsor funds.";

  const lowerCode = code.toLowerCase();
  if (cat === 'work' || lowerCode.includes('wrk') || lowerCode.includes('arbeidstillatelse') || lowerCode.includes('blue-card')) {
    fundsMin = "Norway Work Permit (Arbeidstillatelse / Skilled Worker) requires a binding job offer from a Norwegian employer + gross annual salary meeting UDI threshold (min NOK 300,000/year or NOK 600,000/year for EU Blue Card) + company registration in Brønnøysundregistrene.";
    fundsBankMonths = "Norwegian employer job offer, employment contract, and 3-6 months bank statements.";
    fundsSudden = "Employment contract must specify gross annual salary in NOK, job title, and full-time position.";
    fundsEx = "✅ Sahi: Official job offer + signed contract (NOK 300,000+/year) + Brønnøysund firm registration + 6M statements. ❌ Galat: Salary below threshold or part-time contract.";
  } else if (cat === 'student' || lowerCode.includes('stu') || lowerCode.includes('residence-permit')) {
    fundsMin = "Norway Student Residence Permit requires official admission letter from an accredited Norwegian university / college + tuition fee receipt + proof of living funds of at least NOK 151,690 per academic year deposited in a Norwegian bank account or university deposit account.";
    fundsBankMonths = "3-6 months bank statements showing min NOK 151,690 liquid balance.";
    fundsSudden = "Funds must be deposited into Norwegian student deposit bank account prior to visa issuance.";
    fundsEx = "✅ Sahi: University acceptance letter + NOK 151,690 in student deposit account. ❌ Galat: Unverified sponsor funds or missing deposit receipt.";
  } else if (cat === 'family' || lowerCode.includes('fam') || lowerCode.includes('reunification') || lowerCode.includes('samboer')) {
    fundsMin = "Norway Family Reunification Residence Permit requires sponsor in Norway to meet annual income threshold (min NOK 320,000/year gross before tax) + Guarantee Form for Visits + apostilled marriage / samboer cohabitation proof (min 2 years joint living).";
    fundsBankMonths = "6 months bank statements and tax return (Skattemelding) of sponsor in Norway.";
    fundsSudden = "Guarantee Form for Visits certified by Norwegian Police / UDI required for host sponsorship.";
    fundsEx = "✅ Sahi: Certified Guarantee Form + sponsor income proof (NOK 320,000+) + apostilled marriage/samboer proof. ❌ Galat: Sponsor income below NOK 320k.";
  } else if (cat === 'business' || lowerCode.includes('biz') || lowerCode.includes('entrepreneur')) {
    fundsMin = "Norway C Business Visa / Self-Employed Permit requires an official invitation letter from a company registered in Norway in Brønnøysundregistrene + home employer dispatch letter + for self-employed, startup capital of min NOK 100,000.";
    fundsBankMonths = "3-6 months corporate and personal bank statements.";
    fundsSudden = "Sponsoring Norwegian company must be active in Brønnøysundregistrene commercial registry.";
    fundsEx = "✅ Sahi: Official invitation on Norwegian firm letterhead + Brønnøysund registration + NOK 100k startup proof. ❌ Galat: Unregistered host firm.";
  } else if (cat === 'pr' || lowerCode.includes('pr') || lowerCode.includes('oppholdstillatelse') || lowerCode.includes('spe')) {
    fundsMin = "Norway Permanent Oppholdstillatelse (PR) requires 3 years continuous legal residence on work/family permit + Norwegian language test (min Level A2/B1) and social studies course + self-sufficiency income proof for past 12 months + clean criminal record.";
    fundsBankMonths = "3 years employment history, Skattemelding tax assessments, and bank statements.";
    fundsSudden = "Continuous residence history evaluated by UDI.";
    fundsEx = "✅ Sahi: 3 years legal residence history + NOK 300k+ income + Norwegian B1 certificate. ❌ Galat: Unexcused gap in legal stay or tax arrears.";
  }

  return {
    fundsBox: { minimum: fundsMin, bankMonths: fundsBankMonths, suddenDeposit: fundsSudden, example: fundsEx },
    itrBox: { years: itrYears, match: itrMatch, noItr: itrNoItr },
    bankBox: { months: bankMonths, regularCredit: bankReg, fd: bankFd, source: bankSource }
  };
}

